    if (ifac[0] != 24 || ifac[1] != 3 || ifac[2] != 2 || ifac[3] != 4 || ifac[4] != 3) return fail("factorisation");

    /* round trip: backward(forward(x)) == n * x */
    for (i = 0; i < n; i++) x[i] = y[i] = (float)((i * 7 % 11) - 5) * 0.25f;
    drftf1(n, y, ch, trig + n, ifac);
    drftb1(n, y, ch, trig + n, ifac);
    for (i = 0; i < n; i++)
        if (std::fabs(y[i] - n * x[i]) > 1e-3f) return fail("round trip");

    /* a cosine at bin 3 */
    for (k = 1; k <= 2; k++) {
        for (i = 0; i < n; i++) y[i] = (float)std::cos(2.0 * 3.14159265358979 * 3 * i / n) * (float)k;
        drftf1(n, y, ch, trig + n, ifac);
        for (i = 0; i < n; i++) {
            float want = (i == 5) ? (float)(n / 2 * k) : 0.f;    /* c[2*3-1] = n/2 * amplitude */
            if (std::fabs(y[i] - want) > 1e-3f) return fail("cosine bin");
